import type {
  InputOptions,
  NormalizedOutputOptions,
  OutputBundle,
  OutputChunk,
  OutputAsset,
  Plugin,
  PluginContext,
} from "rollup";
import type { IsomorphicRollupFs } from "../../src/fs-iface";
import uiPageSourceManifest from "../../src/ui-page-source-manifest";
import type { UiPageSourceManifest } from "../../src/ui-page-source-manifest";

describe("Source Manifest plugin", () => {
  const createMockFs = (): IsomorphicRollupFs => ({
    access: async () => true,
    readFile: async () => "",
    stat: async () => ({
      isFile: () => true,
      isDirectory: () => false,
      isSymbolicLink: () => false,
      type: "file" as const,
      mode: 0o644,
      size: 0,
      ino: 1,
      mtimeMs: Date.now(),
      ctimeMs: Date.now(),
      uid: 1,
      gid: 1,
      dev: 1,
    }),
    lstatSync: () =>
      ({
        isFile: () => true,
        isDirectory: () => false,
        isSymbolicLink: () => false,
      }) as ReturnType<NonNullable<IsomorphicRollupFs["lstatSync"]>>,
    readdir: async () => [],
    realpath: async (path: string) => path,
    realpathSync: (path: string) => path,
    mkdir: async () => {},
    writeFile: async () => {},
  });

  const createMockContext = (): PluginContext => {
    const emittedFiles: Array<{
      type: string;
      fileName: string;
      source: string;
    }> = [];
    return {
      emitFile: jest.fn((file: any) => {
        emittedFiles.push(file);
        return file.fileName;
      }),
      getEmittedFiles: () => emittedFiles,
      warn: jest.fn(),
      error: jest.fn(),
    } as unknown as PluginContext & { getEmittedFiles: () => any[] };
  };

  const createMockChunk = (
    name: string,
    fileName: string,
    modules: Record<string, any> = {},
  ): OutputChunk =>
    ({
      type: "chunk",
      name,
      fileName,
      code: "console.log('bundled');",
      isEntry: true,
      facadeModuleId: `/project/${name}.js`,
      isDynamicEntry: false,
      moduleIds: Object.keys(modules),
      exports: [],
      imports: [],
      dynamicImports: [],
      implicitlyLoadedBefore: [],
      modules,
      map: null,
      sourcemapFileName: null,
      preliminaryFileName: fileName,
      importedBindings: {},
      referencedFiles: [],
    }) as unknown as OutputChunk;

  const createMockAsset = (fileName: string, source: string): OutputAsset =>
    ({
      type: "asset",
      fileName,
      source,
      name: fileName,
      needsCodeReference: false,
    }) as OutputAsset;

  const callGenerateBundleHook = async (
    plugin: Plugin,
    context: PluginContext,
    bundle: OutputBundle,
  ) => {
    const hook = plugin.generateBundle;
    if (typeof hook === "function") {
      return await hook.call(
        context,
        {} as NormalizedOutputOptions,
        bundle,
        false,
      );
    }
  };

  describe("Basic Functionality", () => {
    test("should generate manifest for a single HTML file with one entry", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "export default App",
            originalLength: 18,
            removedExports: [],
            renderedExports: [],
            renderedLength: 18,
          },
          "/project/src/client/components/Button.tsx": {
            code: "export const Button = () => {}",
            originalLength: 30,
            removedExports: [],
            renderedExports: [],
            renderedLength: 30,
          },
        }),
        "index.html": createMockAsset(
          "index.html",
          "<html><body></body></html>",
        ),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      expect(emittedFiles.length).toBe(1);

      const manifestFile = emittedFiles[0];
      expect(manifestFile.fileName).toBe("index.ui-source-manifest.json");
      expect(manifestFile.type).toBe("asset");

      const manifest: UiPageSourceManifest = JSON.parse(manifestFile.source);
      expect(manifest).toHaveProperty("html");
      expect(manifest).toHaveProperty("entry");
      expect(manifest).toHaveProperty("files");
      expect(manifest.html).toBe("src/client/index.html");
      expect(manifest.entry).toBeTruthy();
      expect(manifest.files).toEqual([
        "src/client/app.tsx",
        "src/client/components/Button.tsx",
        "src/client/index.html",
      ]);
    });

    test("should handle multiple entries in the same HTML", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "export default App",
            originalLength: 18,
            removedExports: [],
            renderedExports: [],
            renderedLength: 18,
          },
        }),
        "vendor.js": createMockChunk("vendor", "vendor.js", {
          "/project/src/client/vendor.ts": {
            code: "export const vendor = true",
            originalLength: 26,
            removedExports: [],
            renderedExports: [],
            renderedLength: 26,
          },
        }),
        "index.html": createMockAsset(
          "index.html",
          "<html><body></body></html>",
        ),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);

      expect(manifest.html).toBe("src/client/index.html");
      expect(manifest.files).toContain("src/client/app.tsx");
      expect(manifest.files).toContain("src/client/vendor.ts");
    });

    test("should deduplicate files across multiple chunks", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const sharedModule = {
        "/project/src/client/shared.ts": {
          code: "export const shared = true",
          originalLength: 26,
          removedExports: [],
          renderedExports: [],
          renderedLength: 26,
        },
      };

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          ...sharedModule,
          "/project/src/client/app.tsx": {
            code: "import { shared } from './shared'",
            originalLength: 34,
            removedExports: [],
            renderedExports: [],
            renderedLength: 34,
          },
        }),
        "page.html": createMockAsset("page.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);

      const sharedCount = manifest.files.filter(
        (f) => f === "src/client/shared.ts",
      ).length;
      expect(sharedCount).toBe(1);
    });
  });

  describe("Filtering and Exclusion", () => {
    test("should filter out virtual modules (starting with \\0)", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "export default App",
            originalLength: 18,
            removedExports: [],
            renderedExports: [],
            renderedLength: 18,
          },
          "\0virtual-module": {
            code: "virtual",
            originalLength: 7,
            removedExports: [],
            renderedExports: [],
            renderedLength: 7,
          },
        }),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);

      expect(manifest.files).not.toContain("virtual-module");
      expect(manifest.files).toContain("src/client/app.tsx");
    });

    test("should filter out Rollup internals ($insertStyle, ___)", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "export default App",
            originalLength: 18,
            removedExports: [],
            renderedExports: [],
            renderedLength: 18,
          },
          "/project/$insertStyle": {
            code: "function insertStyle(){}",
            originalLength: 24,
            removedExports: [],
            renderedExports: [],
            renderedLength: 24,
          },
          "/project/___module": {
            code: "internal",
            originalLength: 8,
            removedExports: [],
            renderedExports: [],
            renderedLength: 8,
          },
        }),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);

      expect(manifest.files).not.toContain("$insertStyle");
      expect(manifest.files).not.toContain("___module");
    });

    test("should use default exclude patterns (node_modules, dist, etc.)", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "app",
            originalLength: 3,
            removedExports: [],
            renderedExports: [],
            renderedLength: 3,
          },
          "/project/node_modules/react/index.js": {
            code: "react",
            originalLength: 5,
            removedExports: [],
            renderedExports: [],
            renderedLength: 5,
          },
          "/project/dist/build.js": {
            code: "build",
            originalLength: 5,
            removedExports: [],
            renderedExports: [],
            renderedLength: 5,
          },
          "/project/.now/temp.js": {
            code: "temp",
            originalLength: 4,
            removedExports: [],
            renderedExports: [],
            renderedLength: 4,
          },
          "/project/.git/hooks/pre-commit": {
            code: "git",
            originalLength: 3,
            removedExports: [],
            renderedExports: [],
            renderedLength: 3,
          },
        }),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);

      expect(manifest.files).toContain("src/client/app.tsx");
      expect(manifest.files.some((p) => p.includes("node_modules"))).toBe(
        false,
      );
      expect(manifest.files.some((p) => p.includes("dist"))).toBe(false);
      expect(manifest.files.some((p) => p.includes(".now"))).toBe(false);
      expect(manifest.files.some((p) => p.includes(".git"))).toBe(false);
    });

    test("should support custom exclude patterns with picomatch", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
        excludePatterns: ["**/*.test.ts", "**/__tests__/**", "**/vendor/**"],
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "app",
            originalLength: 3,
            removedExports: [],
            renderedExports: [],
            renderedLength: 3,
          },
          "/project/src/client/app.test.ts": {
            code: "test",
            originalLength: 4,
            removedExports: [],
            renderedExports: [],
            renderedLength: 4,
          },
          "/project/src/client/__tests__/setup.ts": {
            code: "setup",
            originalLength: 5,
            removedExports: [],
            renderedExports: [],
            renderedLength: 5,
          },
          "/project/vendor/lib.js": {
            code: "lib",
            originalLength: 3,
            removedExports: [],
            renderedExports: [],
            renderedLength: 3,
          },
        }),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);

      expect(manifest.files).toContain("src/client/app.tsx");
      expect(manifest.files.some((p) => p.includes(".test.ts"))).toBe(false);
      expect(manifest.files.some((p) => p.includes("__tests__"))).toBe(false);
      expect(manifest.files.some((p) => p.includes("vendor"))).toBe(false);
    });
  });

  describe("Output Configuration", () => {
    test("should handle nested HTML files", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "new-pages/contact-2.js": createMockChunk(
          "new-pages/contact-2",
          "new-pages/contact-2.js",
          {
            "/project/src/client/new-pages/contact-2.tsx": {
              code: "export default Contact2",
              originalLength: 22,
              removedExports: [],
              renderedExports: [],
              renderedLength: 22,
            },
          },
        ),
        "new-pages/contact-2.html": createMockAsset(
          "new-pages/contact-2.html",
          "<html><body></body></html>",
        ),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      expect(emittedFiles.length).toBe(1);
      expect(emittedFiles[0].fileName).toBe(
        "new-pages/contact-2.ui-source-manifest.json",
      );

      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);
      expect(manifest.html).toBe("src/client/new-pages/contact-2.html");
      expect(manifest.files).toContain("src/client/new-pages/contact-2.tsx");
    });

    test("should place manifest alongside HTML file", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "app",
            originalLength: 3,
            removedExports: [],
            renderedExports: [],
            renderedLength: 3,
          },
        }),
        "pages/admin/index.html": createMockAsset(
          "pages/admin/index.html",
          "<html></html>",
        ),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      expect(emittedFiles[0].fileName).toBe(
        "pages/admin/index.ui-source-manifest.json",
      );
    });

    test("should produce sorted file paths for consistency", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/z-last.ts": {
            code: "last",
            originalLength: 4,
            removedExports: [],
            renderedExports: [],
            renderedLength: 4,
          },
          "/project/src/client/a-first.ts": {
            code: "first",
            originalLength: 5,
            removedExports: [],
            renderedExports: [],
            renderedLength: 5,
          },
          "/project/src/client/m-middle.ts": {
            code: "middle",
            originalLength: 6,
            removedExports: [],
            renderedExports: [],
            renderedLength: 6,
          },
        }),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);

      const sortedPaths = [...manifest.files].sort();

      expect(manifest.files).toEqual(sortedPaths);
    });
  });

  describe("Edge Cases", () => {
    test("should find HTML source from chunk modules", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "export default App",
            originalLength: 18,
            removedExports: [],
            renderedExports: [],
            renderedLength: 18,
          },
          "/project/src/index.html": {
            code: "<html></html>",
            originalLength: 13,
            removedExports: [],
            renderedExports: [],
            renderedLength: 13,
          },
        }),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      expect(emittedFiles.length).toBe(1);

      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);
      expect(manifest.html).toBe("src/client/index.html");
      expect(manifest.files).toContain("src/client/app.tsx");
      expect(manifest.files).toContain("src/client/index.html");
    });

    test("should handle bundle with no HTML files", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "app",
            originalLength: 3,
            removedExports: [],
            renderedExports: [],
            renderedLength: 3,
          },
        }),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      expect(emittedFiles.length).toBe(0);
    });

    test("should handle bundle with no chunks", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      expect(emittedFiles.length).toBe(0);
    });

    test("should handle chunk with no modules", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {}),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      expect(emittedFiles.length).toBe(1);

      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);
      expect(manifest.files).toEqual(["src/client/index.html"]);
      expect(manifest.entry).toBe("app.js");
    });

    test("should handle empty exclude patterns array", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
        excludePatterns: [],
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "app",
            originalLength: 3,
            removedExports: [],
            renderedExports: [],
            renderedLength: 3,
          },
          "/project/node_modules/react/index.js": {
            code: "react",
            originalLength: 5,
            removedExports: [],
            renderedExports: [],
            renderedLength: 5,
          },
        }),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifest: UiPageSourceManifest = JSON.parse(emittedFiles[0].source);

      expect(manifest.files).toContain("src/client/app.tsx");
      expect(manifest.files).toContain("node_modules/react/index.js");
    });
  });

  describe("Manifest Format", () => {
    test("should generate valid JSON with correct structure", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "app",
            originalLength: 3,
            removedExports: [],
            renderedExports: [],
            renderedLength: 3,
          },
        }),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifestSource = emittedFiles[0].source;

      expect(() => JSON.parse(manifestSource)).not.toThrow();

      const manifest: UiPageSourceManifest = JSON.parse(manifestSource);

      // Should have correct structure
      expect(manifest).toHaveProperty("html");
      expect(manifest).toHaveProperty("entry");
      expect(manifest).toHaveProperty("files");
      expect(Array.isArray(manifest.files)).toBe(true);
      expect(typeof manifest.html).toBe("string");
      expect(typeof manifest.entry).toBe("string");
      expect(typeof manifest.files[0]).toBe("string");
    });

    test("should format JSON with 2-space indentation", async () => {
      const plugin = uiPageSourceManifest({
        rootDir: "/project",
        clientDir: "/project/src/client",
        fs: createMockFs(),
      });

      const context = createMockContext();

      const bundle: OutputBundle = {
        "app.js": createMockChunk("app", "app.js", {
          "/project/src/client/app.tsx": {
            code: "app",
            originalLength: 3,
            removedExports: [],
            renderedExports: [],
            renderedLength: 3,
          },
        }),
        "index.html": createMockAsset("index.html", "<html></html>"),
      };

      await callGenerateBundleHook(plugin, context, bundle);

      const emittedFiles = (context as any).getEmittedFiles();
      const manifestSource = emittedFiles[0].source;

      expect(manifestSource).toContain('  "html"');
      expect(manifestSource).toContain('  "entry"');
      expect(manifestSource).toContain('  "files"');
    });
  });
});
